function rulesView(){return `<div class="workbench"><section class="rules-panel"><div class="editor-top"><div><h2>Gjentaksregler</h2><span class="rule-count">${rules.length} regler i malen</span></div><button type="button" class="small-button primary" data-action="newRule">+ Ny</button></div><label><span class="sr-only">Finn regel</span><input class="search" type="search" id="ruleSearch" placeholder="Finn en regel" value="${esc(search)}" aria-label="Finn regel"></label><div class="rule-list" id="ruleList">${ruleList()}</div></section><section class="editor"><form id="ruleForm"><div class="editor-top"><div><p class="eyebrow">${selected?'Rediger regel':'Ny regel'}</p><h2>${esc(draft.title||'Beskriv en ny frist')}</h2></div><div class="row-actions">${selected?'<button type="button" data-action="duplicate">Lag kopi</button><button type="button" data-action="deleteRule">Slett</button>':''}</div></div><div id="ruleError" class="error" role="alert" hidden></div><h3 class="step-title"><span>1</span>Hva gjelder fristen?</h3><div class="fields">${field('Tittel','title',draft.title,'text','required maxlength="180"')}${select('Kategori','category',[['Budsjett','Budsjett'],['Gulbok','Gul bok'],['Regnskap','Regnskap']],draft.category)}</div><h3 class="step-title"><span>2</span>Hvordan skal datoen finnes?</h3><div class="type-grid">${TYPES.map(([key,name,example])=>`<label class="type-option"><input type="radio" name="kind" value="${key}" ${draft.kind===key?'checked':''}><span><strong>${name}</strong><small>${example}</small></span></label>`).join('')}</div><div id="ruleFields">${ruleFields()}</div><div class="sentence" aria-live="polite"><p class="eyebrow">Regelen med vanlige ord</p><p id="sentenceText"></p><small id="sentenceExtra"></small></div><label class="option-line"><input type="checkbox" name="election" ${draft.election?'checked':''}><span>Ta hensyn til valgår<small>Beholder prosjektets eksisterende valgårsvalg. Se virkningen i forhåndsvisningen.</small></span></label><details class="details-block"><summary>Kobling og detaljer</summary><div class="fields">${field('Funksjon / løp','loop',draft.loop)}<p class="hint">Et stabilt navn som samler samme funksjon over tid, for eksempel rammefordeling. Fylles automatisk for en ny regel, og kan justeres her.</p></div><p class="election-help">Fast dato og ukedagsregler justeres ved helg til nærmeste ukedag innen samme kalenderår. Helligdager justeres ikke. Relativ forskyvning teller kalenderdager og justeres ikke på nytt for helg.</p><p class="election-help">Valgår avgjøres av kalenderåret datoen faller i: stortingsvalgår gir tentativ måned, kommunevalgår gir markering med bevart dato. Relative regler arver eventuell månedspresisjon.</p></details><h3 class="step-title"><span>3</span>Kontroller resultatet over flere år</h3><div class="preview-head"><h3>Fem budsjettår</h3><label>Fra budsjettår <input type="number" name="previewStart" min="1" max="9995" value="${previewStart}" aria-label="Første budsjettår i forhåndsvisning"></label></div><div id="rulePreview" aria-live="polite"></div><p class="preview-help">Resultatene beregnes fra feltene ovenfor, også før du lagrer. Datoene er eksempler. Bruk «Prøv malen» for å sette midlertidige ankerdatoer.</p><div class="editor-footer"><p id="saveHint">Lagre når regelen og eksempeldatoene stemmer.</p><div class="row-actions"><button type="button" data-action="resetDraft">Forkast endringer</button><button type="submit" class="primary">Lagre regel i demomalen</button></div></div></form></section></div>`}
function ruleList(){const found=rules.filter(r=>(r.title+' '+r.loop).toLowerCase().includes(search.toLowerCase()));return found.map(r=>`<button type="button" class="rule-link" data-rule="${r.id}" aria-pressed="${r.id===selected}"><strong>${esc(r.title||r.loop)}</strong><small>${esc(TYPES.find(t=>t[0]===r.kind)?.[1])}${r.election?' · valgår':''}</small></button>`).join('')||'<p class="empty">Ingen regler i utvalget.</p>'}
