 if(r.kind==='relative'){const candidates=[...new Map(rules.filter(a=>a.id!==r.id).map(a=>[a.loop,a])).values()],manual=!candidates.some(a=>a.loop===r.anchor);content=`<div class="fields">${select('Milepæl','anchorChoice',[['','Velg milepæl'],...candidates.map(a=>[a.loop,a.title||a.loop]),['__manual','Manuelt fastsatt milepæl']],r.anchorChoice==='__manual'?'__manual':r.anchor?(manual?'__manual':r.anchor):'')}${manual&&r.anchor||r.anchorChoice==='__manual'?field('Navn på manuell milepæl','manualAnchorName',r.anchor):''}</div><div class="fields">${field('Antall kalenderdager','days',r.days,'number','min="0" max="2147483647" required')}${select('Plassering','direction',[[-1,'Før milepælen'],[1,'Etter milepælen']],r.direction)}</div><p class="hint">Velg 0 dager for samme dag. Milepælens år følger automatisk med; ingen egen årsforskyvning legges til.</p>`}
