function updateLive(){if(!$('sentenceText'))return;const incomplete=valid({...draft,title:draft.title||'Ny regel',loop:draft.loop||'ny-regel'});$('sentenceText').textContent=sentence(draft);$('sentenceExtra').textContent=draft.kind==='window'?'Perioden omfatter startdatoen og de neste seks dagene.':draft.kind==='nth'&&draft.nth===5?'Hvis femte forekomst mangler, brukes den siste.':'';if($('windowLabel'))$('windowLabel').textContent=windowText(draft);const pool=effectiveRules().map(r=>r.id===draft.id?{...r,title:r.title||'Ny regel',loop:r.loop||'ny-regel'}:r),r=pool.find(r=>r.id===draft.id);$('rulePreview').innerHTML=`<table class="preview-table"><thead><tr><th>Budsjettår</th><th>Beregnet dato og forklaring</th></tr></thead><tbody>${Array.from({length:5},(_,i)=>{const y=previewStart+i,result=incomplete?{error:incomplete,notes:[]}:calc(r,y,pool);return `<tr><td>${y}</td><td>${resultMarkup(result)}</td></tr>`}).join('')}</tbody></table>`;$('saveHint').textContent=dirty?'Du har endringer som ikke er lagret.':'Lagre når regelen og eksempeldatoene stemmer.'}
function switchDraft(id){if(dirty){confirmAction('Bytte regel?', 'Du har endringer som ikke er lagret i demomalen. Vil du forkaste dem og gå videre?','Forkast og bytt',()=>{dirty=false;selectDraft(id)});return}selectDraft(id)}
function selectDraft(id){selected=id;draft=id?clone(rules.find(r=>r.id===id)):defaults();dirty=false;render()}
function collect(target){const n=target.name,v=target.value;if(n==='previewStart'){const value=Number(v);if(Number.isInteger(value)&&value>=1&&value<=9995)previewStart=value;return}if(n==='title'){draft.title=v;if(!selected)draft.loop=slug(v)}if(n==='loop')draft.loop=v.trim();if(n==='category')draft.category=v;if(n==='election')draft.election=target.checked;if(['month','day','nth','weekday','days','direction'].includes(n))draft[n]=Number(v);if(n==='kind')draft.kind=v;if(n==='shiftDirection'){const amount=Math.abs(draft.shift)||1;draft.shift=v==='same'?0:v==='before'?-amount:amount}if(n==='shiftCount')draft.shift=(draft.shift<0?-1:1)*Number(v);if(n==='anchorChoice'){draft.anchorChoice=v;draft.anchor=v==='__manual'?'':v}if(n==='manualAnchorName')draft.anchor=v.trim();dirty=true}
function saveRule(e){e.preventDefault();const error=valid(draft);if(error){$('ruleError').textContent=error;$('ruleError').hidden=false;return}const pool=effectiveRules(),cycle=calc(draft,2026,pool).error?.includes('Sirkulær');if(cycle){$('ruleError').textContent='Milepælene peker tilbake på hverandre. Velg en annen milepæl.';$('ruleError').hidden=false;return}const commit=()=>{const index=rules.findIndex(r=>r.id===draft.id);if(index<0)rules.push(clone(draft));else rules[index]=clone(draft);selected=draft.id;dirty=false;render();notify('Regelen er lagret i demomalen. Ingen konkrete frister er endret eller publisert.')};const old=rules.find(r=>r.id===draft.id);if(old&&old.loop!==draft.loop&&rules.some(r=>r.anchor===old.loop))confirmAction('Endre funksjonsnavn?', 'Andre regler bruker det nåværende funksjonsnavnet som milepæl. Koblingene må gjennomgås etter navneendringen.','Lagre nytt funksjonsnavn',commit);else commit()}
function allAnchors(){return [...new Set(rules.filter(r=>r.kind==='relative').map(r=>r.anchor))].filter(Boolean)}
function tryView(){const results=rules.map(r=>({r,result:calc(r,targetYear)}));return `<section class="surface"><h2>Prøv hele malen for ett budsjettår</h2><p>Kontroller samspillet mellom reglene. Dette er en beregning, og oppretter verken frister eller forslag.</p><div class="fields">${field('Budsjettår','targetYear',targetYear,'number','min="1" max="9999"')}<div class="field"><span class="hint">${rules.length} lagrede regler · ulagrert regelutkast er ikke med</span><button type="button" data-action="recalculate">Beregn på nytt</button></div></div><details id="anchorDetails" class="details-block" ${anchorOpen||allAnchors().some(a=>!rules.some(r=>r.loop===a))?'open':''}><summary>Sett dato for en milepæl i dette eksempelet</summary><p class="preview-help">En manuelt satt dato overstyrer beregningen for dette budsjettåret, slik dagens generering støtter. Årsmalregelen endres ikke.</p>${allAnchors().map(loop=>`<label class="anchor-entry"><span>${esc(anchorName(loop))}</span><input id="anchor-${esc(slug(loop))}" type="date" data-anchor="${esc(loop)}" value="${esc(manualAnchors[targetYear]?.[loop]||'')}" aria-label="Eksempeldato for ${esc(anchorName(loop))}"></label>`).join('')||'<p class="hint">Ingen regler bruker en milepæl ennå.</p>'}<button class="text-button" type="button" data-action="clearAnchors">Fjern eksempeldatoer for dette året</button></details></section><section class="surface"><div class="editor-top"><h2>Resultat for budsjettåret ${targetYear}</h2><span class="tag">Kun forhåndsvisning</span></div>${results.length?results.map(({r,result})=>`<div class="result-card"><div><strong>${esc(r.title||r.loop)}</strong><p>${esc(sentence(r))}</p><button type="button" data-edit="${r.id}">Rediger regelen</button></div><div class="calculated">${resultMarkup(result)}</div></div>`).join(''):'<p class="empty">Ingen regler i malen.</p>'}<div class="note">For å opprette faktiske forslag velger administrator senere «Budsjettår og frister → Generer fra årsmal». Godkjenning skjer der for det valgte året. Denne demoen publiserer ingenting.</div></section>`}
function phaseView(){return `<section class="surface"><h2>Felles faser i budsjettløpet</h2><p>Én standardmal for alle år. Faser hjelper leseren å forstå tidslinjen, og beregner ingen fristdatoer.</p><div class="table-scroll"><table class="phase-table"><thead><tr><th>Fase</th><th>Fra og med</th><th>Til og med</th><th></th></tr></thead><tbody>${phases.map((p,i)=>`<tr><td>${esc(p.name)}</td><td>1. ${monthYear(p.start)}</td><td>${monthYear((phases[i+1]?.start??phaseEnd)-1)}</td><td><button type="button" data-phase="${i}">Rediger</button></td></tr>`).join('')}</tbody></table></div><div class="phase-preview">${phases.map((p,i)=>`<div style="flex:${(phases[i+1]?.start??phaseEnd)-p.start}">${esc(p.name)}<small>${monthYear(p.start)} – ${monthYear((phases[i+1]?.start??phaseEnd)-1)}</small></div>`).join('')}</div><p class="preview-help">t er budsjettåret. Alle faseskifter skjer den første i måneden. Endring gjelder alle år og flytter ingen frister.</p></section>`}
function editPhase(index){const p=phases[index];dialog('Rediger felles fase',`<form id="phaseForm">${field('Fasenavn','phaseName',p.name,'text','required')}<div class="fields">${select('Starter i måned','phaseMonth',MONTHS.map((m,i)=>[i,m]),((p.start%12)+12)%12)}${field('År i forhold til budsjettåret','phaseYear',Math.floor(p.start/12),'number','required')}</div><p class="hint">−1 betyr året før budsjettåret. Neste fase bestemmer slutten på denne fasen.</p>${index===phases.length-1?'<div class="fields">'+select('Siste inkluderte måned','endMonth',MONTHS.map((m,i)=>[i,m]),((phaseEnd-1)%12+12)%12)+field('Siste år i forhold til budsjettåret','endYear',Math.floor((phaseEnd-1)/12),'number','required')+'</div>':''}<div id="phaseError" class="error" role="alert" hidden></div><button type="submit" class="primary">Lagre felles fase i demoen</button></form>`,()=>{$('phaseForm').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),start=Number(data.get('phaseYear'))*12+Number(data.get('phaseMonth')),end=index===phases.length-1?Number(data.get('endYear'))*12+Number(data.get('endMonth'))+1:phaseEnd;if(!String(data.get('phaseName')).trim()||index>0&&start<=phases[index-1].start||start>=(phases[index+1]?.start??end)){ $('phaseError').textContent='Velg et navn og stigende fasegrenser.';$('phaseError').hidden=false;return}phases[index]={name:String(data.get('phaseName')).trim(),start};phaseEnd=end;$('infoDialog').close();render();notify('Fasen er oppdatert i den felles demomalen. Ingen fristdatoer er endret.')}})}
function transferView(){return `<section class="surface"><h2>Ta vare på eller hent inn gjentaksregler</h2><p>Eksport og import av årsmal videreføres. Vanlig registrering bruker bare feltene i regelbyggeren.</p><div class="transfer-actions"><button type="button" class="primary" data-action="exportTemplate">Last ned eksempelmal</button><button type="button" data-action="exampleImport">Prøv import med eksempel</button></div><label class="field transfer-file">Åpne malfil for forhåndsvisning<input type="file" id="templateFile" accept=".json,application/json"></label><div class="note">Kun demoens gjentaksregler kan erstattes. Faseinndelingen følger en egen felles mal. Ingen fil sendes til en server.</div></section><section class="surface" id="importPreview">${importPlan?importMarkup():'<h2>Forhåndsvisning før import</h2><p>Velg en malfil eller bruk eksempelet. Du får se hvilke regler som kan tas inn før noe erstattes.</p>'}</section>`}
function importMarkup(){return `<h2>Kontroller før du erstatter demomalen</h2>${importPlan.error?'<div class="error">'+esc(importPlan.error)+'</div>':`<p>${importPlan.good.length} gyldige regler · ${importPlan.bad.length} regler utelates · ${rules.length} eksisterende regler erstattes.</p>${importPlan.good.map(r=>`<div class="import-row"><strong>${esc(r.title||r.loop)}</strong><small>${esc(sentence(r))}</small></div>`).join('')}${importPlan.bad.map(r=>`<div class="import-row"><span class="tag warn">Utelates</span> ${esc(r.loop)}<small>${esc(r.error)}</small></div>`).join('')}<div class="note">Import erstatter hele regelsettet med de gyldige reglene, slik prosjektet gjør i dag. ${importPlan.good.length===0?'Denne importen vil derfor tømme demomalen.':''} Ingen konkrete frister endres.</div><button type="button" class="primary" data-action="confirmImport">Erstatt demomal med ${importPlan.good.length} regler</button>`}`}
function toExport(r){let type,p;if(r.kind==='fixed'){type='FastDato';p={maaned:r.month,dag:r.day,aar_forskyvning:r.shift}}if(['nth','window'].includes(r.kind)){type='RelativUkedag';p={maaned:r.month,ukedag:CODES[r.weekday],aar_forskyvning:r.shift,...r.kind==='window'?{fra_dag:r.day}:{uke:r.nth}}}if(r.kind==='relative'){type='RelativTilMilepael';p={anker_loep:r.anchor,offset_dager:r.days*r.direction}}return {id:r.id,loep:r.loop,tittel:r.title,kategori:r.category,regeltype:type,regelparametre:JSON.stringify(p),valgaarssensitiv:r.election}}
const lower=o=>Object.fromEntries(Object.entries(o??{}).map(([k,v])=>[k.toLowerCase(),v]));
function parseImport(value){try{const root=lower(value);if((root.versjon??1)!==1||!Array.isArray(root.regler)||root.regler.some(r=>!r||typeof r!=='object'))throw Error('Filen må være en årsmal med versjon 1 og en liste med regler.');const ids=root.regler.map(r=>lower(r).id).filter(Boolean);if(new Set(ids).size!==ids.length)throw Error('Filen har flere regler med samme ID. Hele importen er avvist.');let good=[],bad=[];for(const raw of root.regler){const e=lower(raw);try{const p=typeof e.regelparametre==='string'?JSON.parse(e.regelparametre):null;if(!p||typeof p!=='object')throw Error('Regelparametrene kan ikke leses.');const r={...defaults(),id:e.id||uuid(),loop:e.loep||'',title:e.tittel||'',category:typeof e.kategori==='number'?['Budsjett','Gulbok','Regnskap'][e.kategori]:e.kategori||'Budsjett',election:e.valgaarssensitiv===true},type=typeof e.regeltype==='number'?['FastDato','RelativUkedag','RelativTilMilepael'][e.regeltype]:e.regeltype;if(type==='FastDato')Object.assign(r,{kind:'fixed',month:p.maaned,day:p.dag,shift:p.aar_forskyvning??0});else if(type==='RelativUkedag'){const weekday=Object.fromEntries([...CODES.map((c,i)=>[c,i]),...DAYS.map((c,i)=>[c,i]),['lør',6],['søn',0]])[p.ukedag?.trim().toLowerCase()];Object.assign(r,{kind:p.fra_dag!=null?'window':'nth',month:p.maaned,day:p.fra_dag??20,nth:p.uke??2,weekday,shift:p.aar_forskyvning??0})}else if(type==='RelativTilMilepael')Object.assign(r,{kind:'relative',anchor:p.anker_loep||'',days:Math.abs(p.offset_dager),direction:p.offset_dager<0?-1:1});else throw Error('Ukjent regeltype.');const err=valid({...r,title:r.title||r.loop});if(err)throw Error(err);good.push(r)}catch(e2){bad.push({loop:e.loep||'Ukjent regel',error:e2.message})}}return {good,bad}}catch(e){return {error:e.message}}}
function download(){const data={versjon:1,eksportertTid:new Date().toISOString(),regler:rules.map(toExport)},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='atelier-aarsmal-eksempel.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Eksempelmalen er lastet ned. Den inneholder bare demoens regler.')}
function guardTab(next){if(dirty){confirmAction('Forlate regelutkastet?', 'Endringene er ikke lagret. Du kan bli her og lagre, eller forkaste dem før du bytter område.','Forkast og gå videre',()=>{dirty=false;draft=selected?clone(rules.find(r=>r.id===selected)):defaults();tab=next;render()})}else{tab=next;render()}}
document.addEventListener('input',e=>{if(e.target.id==='ruleSearch'){search=e.target.value;$('ruleList').innerHTML=ruleList();return}if(e.target.closest('#ruleForm')&&e.target.matches('input:not([type=radio]):not([type=checkbox]),textarea')){collect(e.target);updateLive()}});
document.addEventListener('change',async e=>{
 if(e.target.closest('#ruleForm')&&e.target.matches('select,input[type=radio],input[type=checkbox]')){collect(e.target);if(['kind','shiftDirection','anchorChoice'].includes(e.target.name)){$('ruleFields').innerHTML=ruleFields();document.querySelectorAll('[name=kind]').forEach(n=>n.checked=n.value===draft.kind)}updateLive()}
 if(e.target.name==='targetYear'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=1&&n<=9999){targetYear=n;render()}}
 if(e.target.dataset.anchor){manualAnchors[targetYear]??={};if(e.target.value)manualAnchors[targetYear][e.target.dataset.anchor]=e.target.value;else delete manualAnchors[targetYear][e.target.dataset.anchor];render()}
 if(e.target.id==='templateFile'){const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){importPlan={error:'Velg en malfil under 2 MB.'};render();return}try{importPlan=parseImport(JSON.parse(await file.text()))}catch{importPlan={error:'Filen inneholder ikke en lesbar mal.'}}render()}
});
document.addEventListener('submit',e=>{if(e.target.id==='ruleForm')saveRule(e)});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.rule)switchDraft(b.dataset.rule);if(b.dataset.tab)guardTab(b.dataset.tab);if(b.dataset.edit){tab='rules';selectDraft(b.dataset.edit)}if(b.dataset.phase!==undefined)editPhase(Number(b.dataset.phase));
 if(b.dataset.nav){if(b.dataset.nav==='template')return;const n=NAV.find(x=>x[0]===b.dataset.nav);dialog(n[1],`<p>${esc(n[2])}</p><div class="note">Dette er foreslått inndeling. Bare Årsmal er bygget i denne separate demoen.</div>`)}
 const action=b.dataset.action;
 if(action==='navProposal')dialog('Forslag til administrasjonsmeny','<div class="menu-map">'+NAV.map(([,name,text])=>'<section><h3>'+esc(name)+'</h3><p>'+esc(text)+'</p></section>').join('')+'</div>');
 if(action==='readerInfo')dialog('Leservisningene videreføres','<p>Kalender og Budsjettår videreføres fra Atelier-utkastet. Denne demoen utforsker bare Årsmal og den foreslåtte administrasjonsmenyen.</p>');
 if(action==='closeDialog')$('infoDialog').close();
 if(action==='newRule')switchDraft(null);
 if(action==='duplicate'){const current=clone(draft);selected=null;draft={...current,id:uuid(),title:current.title+' – kopi',loop:current.loop+'-kopi'};dirty=true;render();notify('Kopien er et nytt utkast. Juster regelen og lagre når den stemmer.')}
 if(action==='resetDraft'){draft=selected?clone(rules.find(r=>r.id===selected)):defaults();dirty=false;render()}
 if(action==='deleteRule'){const r=rules.find(r=>r.id===selected),dependent=rules.filter(a=>a.anchor===r.loop);confirmAction('Slette regelen?',`«${esc(r.title)}» fjernes fra demomalen. ${dependent.length?dependent.length+' andre regler bruker funksjonen som milepæl. Disse beholdes og vil vise behov for ankerdato.':''} Ingen publiserte frister endres.`,'Slett regel',()=>{rules=rules.filter(a=>a.id!==r.id);selectDraft(rules[0]?.id??null);notify('Regelen er slettet fra demomalen.')})}
 if(action==='recalculate')render();if(action==='clearAnchors'){manualAnchors[targetYear]={};render()}
 if(action==='exportTemplate')download();
 if(action==='exampleImport'){const data={versjon:1,regler:[toExport({...defaults(),title:'Eksempel: mandag i juli',loop:'juli-eksempel',kind:'window',shift:-1}),{id:uuid(),loep:'ugyldig-eksempel',tittel:'Eksempel med umulig dato',kategori:'Budsjett',regeltype:'FastDato',regelparametre:'{"maaned":2,"dag":30}'}]};importPlan=parseImport(data);render()}
 if(action==='confirmImport'&&importPlan&&!importPlan.error)confirmAction('Erstatte alle demoens gjentaksregler?',`${importPlan.good.length} gyldige regler tas inn. ${rules.length} eksisterende regler erstattes. ${importPlan.bad.length} ugyldige regler utelates. Faseinndeling og konkrete frister endres ikke.`,'Ja, erstatt demomalen',()=>{rules=clone(importPlan.good);dirty=false;selected=rules[0]?.id??null;draft=selected?clone(rules[0]):defaults();importPlan=null;render();notify('Demomalen er erstattet med de gyldige importreglene.')});
});
render();
